def transform(grid):
    counts = {3: 0, 2: 0}
    for row in grid:
        for color in (2, 3):
            if color in row:
                counts[color] += 1
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
